// C locale is the minimal, guaranteed standard
setlocale(LC_ALL, "C");

// Use system locale (implementation-defined behavior)
const char* current = setlocale(LC_ALL, "");
// Resulting string (current) dictates OS handling

double pi = 3.14159;

// LC_NUMERIC controls number formatting (decimal separator)
setlocale(LC_NUMERIC, "C");
printf("%.3f", pi); // Output: 3.142

// If system locale uses comma (e.g., "fr_FR"):
setlocale(LC_NUMERIC, current);
printf("%.3f", pi); // Output may be: 3,142

// Warning: C++ streams (std::cout) ignore C setlocale
// unless synchronized or explicit std::locale is used.

// Changing locale incurs runtime overhead and memory usage
// due to loading locale-specific data tables.
